import collections, statistics

def health(outputs, baseline_len):
    """운영 출력 묶음에서 세 가지 이상 신호를 센다."""
    alerts = []
    valid = sum(1 for o in outputs if o and 'nan' not in o) / len(outputs)
    if valid < 0.99:
        alerts.append(f'valid {valid:.1%}')            # NaN 류
    med = statistics.median(len(o.split()) for o in outputs)
    if med > 3 * baseline_len:
        alerts.append(f'length {med} vs {baseline_len}')  # 도구 루프 류
    cjk = sum(any('\u4e00' <= ch <= '\u9fff' for ch in o) for o in outputs)
    if cjk / len(outputs) > 0.01:
        alerts.append(f'cjk {cjk}/{len(outputs)}')      # KV 오프바이원 류
    rep = collections.Counter(w for o in outputs for w in o.split())
    return alerts, rep.most_common(1)

print(health(['hello world'] * 98 + ['hi hi hi hi', '你好 hi'], baseline_len=2))

from collections import OrderedDict

class Tier:
    def __init__(self, name, cap): self.name, self.cap, self.d = name, cap, OrderedDict()

def access(tiers, key):
    """tiers[0]=GPU. 찾으면 GPU 로 올리고 넘치는 것은 아래로 LRU 축출."""
    where = next((t.name for t in tiers if key in t.d), 'miss(prefill)')
    for t in tiers: t.d.pop(key, None)
    tiers[0].d[key] = True
    for upper, lower in zip(tiers, tiers[1:]):
        while len(upper.d) > upper.cap:
            old, _ = upper.d.popitem(last=False)   # 가장 오래 안 쓴 것
            lower.d[old] = True
    tiers[-1].d = OrderedDict(list(tiers[-1].d.items())[-tiers[-1].cap:])
    return where

tiers = [Tier('GPU', 2), Tier('CPU', 3), Tier('NVMe', 10)]
for s in ['a', 'b', 'c', 'a', 'd', 'e', 'b', 'f', 'a']:
    print(s, access(tiers, s))

import numpy as np

# IsoFLOP 실험의 최적점들(가상의 값)로 거듭제곱 지수를 맞춘다
C = np.array([1e18, 2e18, 4e18, 8e18, 16e18, 32e18, 64e18])
mu_opt = np.array([2.1, 2.7, 3.5, 4.6, 6.0, 7.9, 10.5])   # 최적 반복 수

slope, intercept = np.polyfit(np.log10(C), np.log10(mu_opt), 1)
print(f'mu_rec* ∝ C^{slope:.2f}')

def predict(c):
    return 10 ** (intercept + slope * np.log10(c))

for c in [1e20, 1e21]:
    print(f'C={c:.0e}: 최적 반복 ≈ {predict(c):.1f}')
